CREATE OR REPLACE FUNCTION public.bix_growth_excluded(p_user uuid) RETURNS boolean LANGUAGE sql STABLE SECURITY DEFINER SET search_path=public AS $$ WITH RECURSIVE ancestors AS (SELECT p_user AS uid, ARRAY[p_user] AS path UNION ALL SELECT r.referred_by, a.path || r.referred_by FROM ancestors a JOIN public.referral_codes r ON r.user_id=a.uid WHERE r.referred_by IS NOT NULL AND NOT r.referred_by=ANY(a.path)) SELECT EXISTS(SELECT 1 FROM ancestors a JOIN public.user_roles u ON u.user_id=a.uid WHERE u.role='reviewer' AND u.user_id='d247372c-9970-4068-a872-85ff24270cbb'::uuid) $$;
CREATE OR REPLACE FUNCTION public.bix_growth_profit_guard() RETURNS trigger LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ BEGIN IF public.bix_growth_excluded(NEW.user_id) THEN RETURN NEW; END IF; PERFORM pg_advisory_xact_lock(hashtext('bix-growth-withdraw')); IF EXISTS(SELECT 1 FROM public.bix_growth_control WHERE id=1 AND frozen) THEN RAISE EXCEPTION 'Withdrawals temporarily paused by Owner 1. Existing records are preserved.'; END IF; RETURN NEW; END $$;
CREATE TRIGGER bix_growth_profit_guard BEFORE INSERT ON public.bix_stake_profit_withdrawals FOR EACH ROW EXECUTE FUNCTION public.bix_growth_profit_guard();
CREATE OR REPLACE FUNCTION public.bix_growth_scope_report() RETURNS jsonb LANGUAGE plpgsql STABLE SECURITY DEFINER SET search_path=public AS $$ BEGIN IF NOT public.is_bix_admin() THEN RAISE EXCEPTION 'Owner access required'; END IF; RETURN jsonb_build_object('owner2_excluded',public.bix_growth_excluded('d247372c-9970-4068-a872-85ff24270cbb'),'owner1_excluded',public.bix_growth_excluded(auth.uid()),'excluded_members',(SELECT count(*) FROM public.referral_codes WHERE public.bix_growth_excluded(user_id))); END $$;
REVOKE ALL ON FUNCTION public.bix_growth_scope_report() FROM PUBLIC,anon; GRANT EXECUTE ON FUNCTION public.bix_growth_scope_report() TO authenticated,service_role;